vertexShader:
uniform float uNow,uArchN0,uArchH,uArchGlow,uMercyRB,uReflect,uAmt,uBreath; uniform vec2 uBase; uniform vec3 uA,uW,uP; uniform float uK[11];
attribute vec2 aMW; varying float vV,vNode,vAmt,vTh;
void main(){
  float t=position.y, side=position.z, mir=aMW.x, w=aMW.y;
  float b=uArchN0+4.00000*position.x+0.25000*t;
  float th=1.57079633*t, xl=side*7.00000*sin(th), yl=mir*uArchH*cos(th);
  vec3 sc=sin(uW*b+uP); float cx=dot(uA,sc)-uBase.x-uBase.y*(b-uNow);
  float u=(b-uNow)*27.00000;
  vec3 Pc=vec3(cx+xl, yl, -u);
  float d=length((viewMatrix*vec4(Pc,1.0)).xyz);
  float hw=clamp(3.20000*d/494.81883,0.06000,2.60000);
  vec2 rad=normalize(vec2(xl,yl)+vec2(0.0,1e-4));
  gl_Position=projectionMatrix*viewMatrix*vec4(Pc+vec3(rad*(hw*w),0.0),1.0);
  float mercy=uK[int(position.x)];
  float fade=1.0-smoothstep(734.40000,864.00000,abs(u));
  float hlf=mix(1.0, mix(uReflect,1.0,mercy), step(mir,0.0));
  vV=w; vTh=th; vNode=smoothstep(0.86,1.0,abs(t));
  vAmt=uAmt*uArchGlow*mix(fade,sqrt(fade),mercy)*mix(1.0,uMercyRB,mercy)*hlf*(1.0+uBreath*0.45000);
}

fragmentShader:
uniform vec3 uCol; uniform float uArchPrism; varying float vV,vNode,vAmt,vTh;
void main(){
  if(vAmt<=0.003) discard;
  float core=exp(-vV*vV*16.00000)*(1.0+2.20000*vNode);
  vec3 col=uCol;
  float o=max(vV,0.0), q=vV-(-0.55000);
  float ie=exp(-q*q*22.00000);
  float aur=exp(-o*o*2.40000)*step(0.001,o)*0.34;
  col=mix(col, vec3(0.58)+0.42*cos(vec3(vTh*2.4)+vec3(0.0,2.094,4.189)), clamp(uArchPrism*ie,0.0,1.0));
  float a=(core+aur+ie*0.30)*vAmt;
  if(a<=0.003) discard;
  gl_FragColor=vec4(col*a, a);
}
